/* ── State ─────────────────────────────────────────────── */
const $ = (sel) => document.querySelector(sel);
const year = new Date().getFullYear();
let FULL = null;          // full posts (with body)
let fullPromise = null;
let activeYear = "all";
let searchQuery = "";
let currentPostId = null;

const TABS = [
  ["home", "home.exe"],
  ["about", "about.exe"],
  ["links", "links.exe"],
];

/* ── Boot screen (fast load) ──────────────────────────── */
function runBoot() {
  const fill = $("#boot-fill");
  let p = 0;
  const timer = setInterval(() => {
    p += 12 + Math.random() * 22;
    if (p >= 100) {
      p = 100;
      clearInterval(timer);
      setTimeout(() => finishBoot(), 220);
    }
    if (fill) fill.style.width = p + "%";
  }, 110);

  // Failsafe: never leave the boot screen stuck even if the timer stalls.
  setTimeout(finishBoot, 4500);

  const skip = () => { clearInterval(timer); finishBoot(); };
  document.addEventListener("keydown", skip, { once: true });
  document.addEventListener("click", skip, { once: true });
}

function finishBoot() {
  const boot = $("#boot");
  if (!boot || boot.classList.contains("done")) return;
  boot.classList.add("done");
  $("#app").classList.remove("hidden");
  setTimeout(() => boot.remove(), 450);
}

/* ── Tabs ──────────────────────────────────────────────── */
function renderTabs() {
  const nav = $("#tabs");
  nav.innerHTML = "";
  TABS.forEach(([id, label], idx) => {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.dataset.tab = id;
    btn.innerHTML = `<span class="idx">${String(idx + 1).padStart(2, "0")}</span>${label}`;
    btn.addEventListener("click", () => switchTab(id));
    nav.appendChild(btn);
  });
}

function switchTab(id) {
  if (id !== "home") currentPostId = null;
  document.querySelectorAll("#tabs button").forEach((b) => b.classList.toggle("active", b.dataset.tab === id));
  document.querySelectorAll(".panel").forEach((p) => p.classList.toggle("active", p.id === `tab-${id}`));
  const panel = $(`#tab-${id}`);
  if (panel) $("#win-title").textContent = panel.dataset.title || "";
  if (id === "home") $("#content").scrollTop = 0;
}

/* ── Home ──────────────────────────────────────────────── */
function yearsAvailable() {
  const set = new Set(POSTS.map((p) => (p.date || "").slice(0, 4)).filter(Boolean));
  return [...set].sort().reverse();
}

function renderHome() {
  const el = $("#tab-home");
  const years = yearsAvailable();
  const stats = `
    <div class="hero-stats">
      <div class="stat-row">
        <span class="stat">📚 <b>${POSTS.length}</b> စာအုပ်စာအညွှန်း</span>
        <span class="stat">✍️ <b>${new Set(POSTS.map((p) => p.author)).size}</b> စာရေးဆရာများ</span>
      </div>
      <div class="stat-row">
        <span class="stat">🗓️ <b>${years[0] || "—"}</b> → <b>${years[years.length - 1] || "—"}</b></span>
      </div>
    </div>`;

  const chips = `<button class="chip ${activeYear === "all" ? "active" : ""}" data-year="all">ALL</button>` +
    years.map((y) => `<button class="chip ${activeYear === y ? "active" : ""}" data-year="${y}">${y}</button>`).join("");

  el.innerHTML = `
    <div class="hero">
      <h1>Book Review<span class="caret"></span></h1>
      <p>${escapeHtml(CONFIG.tagline)} — နှစ်သက်ရာ စာအုပ်စာအညွှန်းကို ရှာဖွေဖတ်ရှုနိုင်ပါတယ်။</p>
      ${stats}
    </div>
    <div class="toolbar">
      <input type="text" class="search-bar" id="search-input" placeholder="🔍 စာအုပ်အမည်၊ စာရေးဆရာ (သို့) စကားလုံး ရိုက်ထည့်ပါ..." />
      <div class="chip-row" id="year-chips">${chips}</div>
    </div>
    <div class="post-grid" id="post-grid"></div>`;

  el.querySelector("#search-input").addEventListener("input", (e) => {
    searchQuery = e.target.value.trim().toLowerCase();
    renderGrid();
  });

  el.querySelectorAll("#year-chips .chip").forEach((c) => {
    c.addEventListener("click", () => {
      activeYear = c.dataset.year;
      el.querySelectorAll("#year-chips .chip").forEach((x) => x.classList.toggle("active", x === c));
      renderGrid();
    });
  });

  renderGrid();
}

function filteredPosts() {
  let list = [...POSTS];
  if (activeYear !== "all") list = list.filter((p) => (p.date || "").slice(0, 4) === activeYear);
  if (searchQuery) {
    const q = searchQuery;
    list = list.filter((p) =>
      (p.title || "").toLowerCase().includes(q) ||
      (p.author || "").toLowerCase().includes(q) ||
      (p.excerpt || "").toLowerCase().includes(q) ||
      (p.tags || []).some((t) => t.toLowerCase().includes(q))
    );
  }
  return list.sort((a, b) => (b.date || "").localeCompare(a.date || "") || Number(b.id) - Number(a.id));
}

function renderGrid() {
  const grid = $("#post-grid");
  if (!grid) return;
  const list = filteredPosts();
  if (list.length === 0) {
    grid.innerHTML = '<div class="no-results">🔍 ရှာဖွေချက်နှင့် ကိုက်ညီသည့် ပို့စ် မတွေ့ပါ။</div>';
    return;
  }
  grid.innerHTML = list.map((p) => postCard(p)).join("");
  grid.querySelectorAll(".post-card").forEach((card) => {
    card.addEventListener("click", () => openPost(card.dataset.id));
  });
}

function postCard(p) {
  const img = p.image
    ? `<img src="${escapeAttr(p.image)}" alt="${escapeAttr(p.title)}" loading="lazy" onerror="this.parentElement.innerHTML='<div class=fallback>📖</div>'">`
    : `<div class="fallback">📖</div>`;
  const tags = (p.tags || []).slice(0, 3).map((t) => `<span>#${escapeHtml(t)}</span>`).join("");
  return `
    <article class="post-card" data-id="${escapeAttr(p.id)}" role="button" tabindex="0">
      <div class="card-img">${img}</div>
      <div class="card-body">
        <div class="card-meta"><span>📅 ${escapeHtml(p.date || "")}</span><span>${escapeHtml(p.author || "")}</span></div>
        <h3 class="card-title">${escapeHtml(p.title)}</h3>
        <p class="card-excerpt">${escapeHtml(p.excerpt)}</p>
        ${tags ? `<div class="card-tags">${tags}</div>` : ""}
      </div>
    </article>`;
}

/* ── Full data loading ─────────────────────────────────── */
function loadFullPosts() {
  if (fullPromise) return fullPromise;
  fullPromise = fetch("/data/posts.json")
    .then((r) => {
      if (!r.ok) throw new Error("fetch failed");
      return r.json();
    })
    .then((data) => { FULL = data; return FULL; })
    .catch(() => { FULL = null; return null; });
  return fullPromise;
}

function fullPost(id) {
  if (!FULL) return null;
  return FULL.find((p) => String(p.id) === String(id)) || null;
}

/* ── Article view ──────────────────────────────────────── */
const SITE_META = {
  title: "Whisper Of Words — Book Review Terminal",
  description: "မြန်မာစာအုပ်စာအညွှန်းများ စုစည်းမှု — Free Myanmar book reviews & recommendations.",
  url: "https://whisperofwords-review.pages.dev/",
  image: "https://whisperofwords-review.pages.dev/assets/og-cover.png",
};

function setMeta(property, content) {
  let el = document.querySelector(`meta[property="${property}"]`);
  if (!el) {
    el = document.createElement("meta");
    el.setAttribute("property", property);
    document.head.appendChild(el);
  }
  el.setAttribute("content", content);
}

function plainText(s) {
  return String(s || "").replace(/<[^>]*>/g, " ").replace(/\s+/g, " ").trim();
}

function applyPostMeta(post) {
  document.title = `${post.title} — Whisper Of Words`;
  setMeta("og:title", post.title);
  setMeta("og:description", plainText(post.excerpt || post.title).slice(0, 200));
  setMeta("og:url", `${location.origin}/review/${post.id}`);
  setMeta("og:image", post.image || SITE_META.image);
}

function resetMeta() {
  document.title = SITE_META.title;
  setMeta("og:title", SITE_META.title);
  setMeta("og:description", SITE_META.description);
  setMeta("og:url", SITE_META.url);
  setMeta("og:image", SITE_META.image);
}

function openPost(id) {
  const post = POSTS.find((p) => String(p.id) === String(id));
  if (!post) return;
  currentPostId = id;
  applyPostMeta(post);
  if (window.history && window.history.pushState) {
    window.history.pushState({ post: id }, "", `/review/${id}`);
  } else {
    location.hash = `/post/${id}`;
  }
  document.querySelectorAll("#tabs button").forEach((b) => b.classList.remove("active"));
  document.querySelectorAll(".panel").forEach((p) => p.classList.toggle("active", p.id === "post-view"));
  $("#win-title").textContent = "read.exe";
  const el = $("#post-view");
  el.innerHTML = articleLoading(post);

  const full = fullPost(id);
  if (full && full.body) {
    renderArticle(post, full);
  } else {
    loadFullPosts().then(() => {
      const now = fullPost(id);
      if (currentPostId === id) renderArticle(post, now && now.body ? now : null);
    });
  }
  $("#content").scrollTop = 0;
  window.scrollTo({ top: 0 });
}

function closePost() {
  currentPostId = null;
  resetMeta();
  if (window.history && window.history.pushState && location.pathname.startsWith("/review/")) {
    window.history.pushState({}, "", "/");
  } else if (location.hash) {
    history.replaceState(null, "", location.pathname);
  }
  switchTab("home");
}

function articleLoading(post) {
  return `
    <a class="back-link" id="btn-back" href="#">← ပင်မစာမျက်နှာသို့</a>
    <div class="article-head">
      <div class="post-meta">📅 ${escapeHtml(post.date || "")} • ✍️ ${escapeHtml(post.author || "")} • #${escapeHtml(post.id)}</div>
      <h1>${escapeHtml(post.title)}</h1>
    </div>
    <div class="article-loading">📖 စာမျက်နှာများ ဖွင့်နေပါသည်...</div>`;
}

function renderArticle(sum, full) {
  const el = $("#post-view");
  const bodyHtml = full && full.body ? full.body : fallbackBody(sum);
  const tags = (full && full.tags && full.tags.length ? full.tags : sum.tags || [])
    .map((t) => `<span>#${escapeHtml(t)}</span>`).join("");
  const mins = full && full.body ? readingTime(full.body) : 0;
  const cover = full && full.image ? full.image : sum.image;
  const canonical = location.origin + "/review/" + sum.id;
  const url = encodeURIComponent(canonical);
  const title = encodeURIComponent(sum.title);

  el.innerHTML = `
    <a class="back-link" id="btn-back" href="#">← ပင်မစာမျက်နှာသို့</a>
    <div class="article">
      <div class="article-head">
        <div class="post-meta">📅 ${escapeHtml(sum.date || "")} • ✍️ ${escapeHtml(sum.author || "")} • #${escapeHtml(sum.id)}</div>
        <h1>${escapeHtml(sum.title)}</h1>
        ${mins ? `<div class="reading-time">📖 ${mins} min ဖတ်ရန်</div>` : ""}
      </div>
      ${cover ? `<img class="article-cover" src="${escapeAttr(cover)}" alt="${escapeAttr(sum.title)}" onerror="this.remove()" loading="lazy">` : ""}
      <div class="article-body">${bodyHtml}</div>
      ${tags ? `<div class="article-tags">${tags}</div>` : ""}
      <div class="share-row">
        <a class="share-btn tg" href="https://t.me/share/url?url=${url}&text=${title}" target="_blank" rel="noopener">📤 Telegram</a>
        <a class="share-btn fb" href="https://www.facebook.com/sharer/sharer.php?u=${url}" target="_blank" rel="noopener">📤 Facebook</a>
        <a class="share-btn viber" href="viber://forward?text=${title}%20${url}" rel="noopener">📤 Viber</a>
        <button class="share-btn copy" id="btn-copy-link" type="button">🔗 Copy Link</button>
      </div>
      <div class="article-actions">
        <button class="btn-bookmark" id="btn-bookmark" type="button">🔖 Save for Later</button>
        ${sum.blog ? `<a class="blog-link" href="${escapeAttr(sum.blog)}" target="_blank" rel="noopener">📄 မူရင်း Blog တွင် ဖတ်ရန် →</a>` : ""}
      </div>
    </div>`;

  el.querySelector("#btn-back").addEventListener("click", (e) => { e.preventDefault(); closePost(); });

  const copy = el.querySelector("#btn-copy-link");
  if (copy) {
    copy.addEventListener("click", () => {
      navigator.clipboard.writeText(canonical).then(() => {
        copy.textContent = "✅ Copied!";
        setTimeout(() => { copy.textContent = "🔗 Copy Link"; }, 1600);
      });
    });
  }

  const bm = el.querySelector("#btn-bookmark");
  if (bm) {
    const list = bookmarks();
    const saved = list.includes(String(sum.id));
    bm.textContent = saved ? "🔖 Saved!" : "🔖 Save for Later";
    bm.classList.toggle("saved", saved);
    bm.addEventListener("click", () => {
      toggleBookmark(sum.id, bm);
    });
  }
}

function fallbackBody(post) {
  return `
    <p>${escapeHtml(post.excerpt || "")}</p>
    ${post.blog ? `<p><a href="${escapeAttr(post.blog)}" target="_blank" rel="noopener">→ ဆက်လက်ဖတ်ရှုရန် မူရင်းစာမျက်နှာသို့</a></p>` : ""}`;
}

function readingTime(html) {
  const txt = html.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim();
  const words = txt.split(" ").length;
  return Math.max(1, Math.ceil(words / 220));
}

/* ── Bookmarks ─────────────────────────────────────────── */
function bookmarks() {
  try { return JSON.parse(localStorage.getItem("wow_bookmarks") || "[]"); } catch { return []; }
}
function toggleBookmark(id, btn) {
  let list = bookmarks();
  const idx = list.indexOf(String(id));
  if (idx > -1) { list.splice(idx, 1); btn.textContent = "🔖 Save for Later"; btn.classList.remove("saved"); }
  else { list.push(String(id)); btn.textContent = "🔖 Saved!"; btn.classList.add("saved"); }
  localStorage.setItem("wow_bookmarks", JSON.stringify(list));
}

