/* ── Routing (path /review/<id> + legacy hash) ────────── */
function postIdFromUrl() {
  const m = location.pathname.match(/^\/review\/(\d+)/);
  if (m) return m[1];
  const h = location.hash.match(/^#\/post\/(\d+)/);
  return h ? h[1] : null;
}

function handleLocation() {
  const id = postIdFromUrl();
  if (id && String(id) !== String(currentPostId)) openPost(id);
}

/* ── Status bar (live clock + battery) ─────────────────── */
function updateClock() {
  const now = new Date();
  const hh = String(now.getHours()).padStart(2, "0");
  const mm = String(now.getMinutes()).padStart(2, "0");
  const timeEl = $("#sb-time");
  if (timeEl) timeEl.textContent = `${hh}:${mm}`;
  const days = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
  const months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  const dateEl = $("#sb-date");
  if (dateEl) {
    dateEl.textContent = `${days[now.getDay()]}, ${now.getDate()} ${months[now.getMonth()]} ${now.getFullYear()}`;
  }
}

function setupBattery() {
  const fill = $("#sb-batt-fill");
  const txt = $("#sb-batt-txt");
  if (!fill || !txt) return;
  const setLevel = (level, charging) => {
    fill.style.width = `${Math.max(0, Math.min(100, level))}%`;
    fill.style.background = level <= 20 ? "#d9480f" : "var(--green)";
    txt.textContent = charging ? `⚡ ${level}%` : `${level}%`;
  };
  if (!navigator.getBattery) { setLevel(0, false); return; }
  navigator.getBattery()
    .then((battery) => {
      const refresh = () => setLevel(Math.round(battery.level * 100), battery.charging);
      refresh();
      battery.addEventListener("levelchange", refresh);
      battery.addEventListener("chargingchange", refresh);
    })
    .catch(() => setLevel(0, false));
}

function renderStatusBar() {
  const nameEl = $("#sb-name");
  if (nameEl) nameEl.textContent = CONFIG.name;
  const avatar = $("#sb-avatar");
  if (avatar) {
    if (CONFIG.avatar) { avatar.src = CONFIG.avatar; avatar.onerror = () => avatar.remove(); }
    else avatar.remove();
  }
  updateClock();
  setInterval(updateClock, 1000);
  setupBattery();
}

/* ── Helpers ───────────────────────────────────────────── */
function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}
function escapeAttr(s) {
  return escapeHtml(s);
}

/* ── Init ──────────────────────────────────────────────── */
function init() {
  renderStatusBar();
  renderTabs();
  renderHome();
  renderAbout();
  renderLinks();
  $("#site-footer").textContent = `System Ready • ${year} — © ${CONFIG.name}`;
  switchTab("home");
  window.addEventListener("popstate", handleLocation);
  window.addEventListener("hashchange", handleLocation);
  runBoot();
  setTimeout(handleLocation, 50);
}

document.addEventListener("DOMContentLoaded", () => {
  // Independent failsafe: app is never left stuck on the boot screen,
  // even if an early init error prevents runBoot() from scheduling one.
  setTimeout(finishBoot, 5000);
  init();
});
